changes.content:
{
  "schema_version": 1,
  "selected_strategy": "shadow-copy-cas",
  "rationale": "Migrate each tenant independently using the existing copy worker, router, and stores. The legacy route remains the sole live writer until cutover. Copy from a durable per-tenant checkpoint, then pause only that tenant's writes for final catch-up, verification, and an atomic route change. If cutover cannot finish within 30 seconds, resume writes on the authoritative route: legacy before a successful CAS, new after it. Retain legacy data as recovery evidence and repair forward on the new store after cutover.",
  "constraints_addressed": ["C1", "C2", "C3", "C4", "C5", "C6", "C7"],
  "rejected_strategies": {
    "global-stop-rewrite": "Stopping all writes violates C1 and prevents independent tenant cutovers under C7.",
    "dual-write-backfill": "Writing to both stores before the route change violates C2.",
    "cdc-mirror-cutover": "A new change-data-capture pipeline and lag monitor violate C6."
  },
  "plan": [
    {
      "step_id": "p1",
      "operation": "capture_initial_watermark",
      "depends_on": [],
      "satisfies": ["C3", "C7"]
    },
    {
      "step_id": "p2",
      "operation": "shadow_copy",
      "depends_on": ["p1"],
      "satisfies": ["C2", "C3", "C6", "C7"]
    },
    {
      "step_id": "p3",
      "operation": "verify_shadow",
      "depends_on": ["p2"],
      "satisfies": ["C4"]
    },
    {
      "step_id": "p4",
      "operation": "freeze_tenant_writes",
      "depends_on": ["p3"],
      "satisfies": ["C1", "C2", "C7"]
    },
    {
      "step_id": "p5",
      "operation": "capture_final_watermark",
      "depends_on": ["p4"],
      "satisfies": ["C4"]
    },
    {
      "step_id": "p6",
      "operation": "copy_delta",
      "depends_on": ["p5"],
      "satisfies": ["C2", "C3"]
    },
    {
      "step_id": "p7",
      "operation": "verify_final",
      "depends_on": ["p6"],
      "satisfies": ["C4"]
    },
    {
      "step_id": "p8",
      "operation": "cas_route",
      "depends_on": ["p7"],
      "satisfies": ["C2", "C4", "C5", "C7"]
    },
    {
      "step_id": "p9",
      "operation": "unfreeze_tenant_writes",
      "depends_on": ["p8"],
      "satisfies": ["C1", "C5", "C7"]
    },
    {
      "step_id": "p10",
      "operation": "monitor",
      "depends_on": ["p9"],
      "satisfies": ["C5", "C6", "C7"]
    }
  ],
  "cutover_gate": {
    "mode": "compare_and_swap",
    "requires": ["legacy_route_version", "final_watermark", "verification_passed"]
  },
  "rollback": {
    "before_cutover": "resume_legacy_and_reuse_checkpoint",
    "after_cutover": "forward_repair_on_new_store"
  },
  "max_tenant_write_pause_seconds": 30
}
